local PUI = _G.PhoenixUI if not (PUI and PUI.gateOpen) then return end
-- ruRU translations (PUI_V2 5.17). Keys are the English strings Phoenix renders
-- (/pui loc lists coverage; .tools/locales.py writes ../keys.txt, and
-- .tools/locale_tokens.py checks every format spec, escape and slash command
-- survives). Game terms follow the Russian client's own wording. Any string
-- not listed falls back to English.
PUI.Locale:Add("ruRU", {
  ["+2 / +3 marks on the timer bar"] = "Отметки +2 / +3 на полосе таймера",
  ["/gg"] = "/gg",
  ["/gg message"] = "Сообщение /gg",
  ["/keys command"] = "Команда /keys",
  ["/pui council <item> asks your group Need, Minor, Transmog or Pass; answers come back with item level. Others need Phoenix with Council on."] = "/pui council <предмет> спрашивает у группы: Нужно, Мелкое улучшение, Трансмогрификация или Отказ; ответы приходят с уровнем предмета. Остальным нужен Phoenix с включённым Council.",
  ["/pui pull [s] (also /pui cd), /pui break [min], /pui rc."] = "/pui pull [с] (или /pui cd), /pui break [мин], /pui rc.",
  ["/pui rl"] = "/pui rl",
  ["/pui simc opens your character as a SimulationCraft profile, ready to copy into SimulationCraft or Raidbots."] = "/pui simc открывает вашего персонажа как профиль SimulationCraft, готовый к копированию в SimulationCraft или Raidbots.",
  ["0 = off. Errors seen in 3 or more sessions become your baseline; when this many errors outside the baseline happen in one session, one chat line says so (once per session)."] = "0 = выкл. Ошибки, замеченные в 3 и более сеансах, становятся базовыми; когда за сеанс случается столько ошибок вне базовых, об этом сообщает одна строка в чате (раз за сеанс).",
  ["0 keeps the summary card open until you close it."] = "0 — карточка итогов остаётся открытой, пока вы её не закроете.",
  ["0 makes the bar background invisible."] = "0 делает фон полосы невидимым.",
  ["0 poor, 1 common, 2 uncommon, 3 rare, 4 epic, 5 legendary, 6 artifact, 7 heirloom."] = "0 низкое, 1 обычное, 2 необычное, 3 редкое, 4 эпическое, 5 легендарное, 6 артефакт, 7 наследуемое.",
  ["12.4K instead of 12,400."] = "12.4K вместо 12,400.",
  ["24-hour clock"] = "24-часовой формат",
  ["24-hour clock block"] = "Блок 24-часовых часов",
  ["24-hour time instead of AM/PM."] = "24-часовое время вместо AM/PM.",
  ["A 1 px theme border around each skinned button."] = "Рамка темы толщиной 1 пикс. вокруг каждой оформленной кнопки.",
  ["A Phoenix button in the inbox that takes only the gold (no items, skips COD) from every mail."] = "Кнопка Phoenix в почтовом ящике, забирающая из всех писем только золото (без предметов, пропуская наложенный платёж).",
  ["A Phoenix search box: items on the page that do not match fade."] = "Поле поиска Phoenix: несовпадающие предметы на странице тускнеют.",
  ["A banner with rising embers when you earn an achievement, time a key or level up. Reduced motion (Glows page) keeps only the banner."] = "Баннер с взлетающими искрами, когда вы получаете достижение, укладываетесь в таймер ключа или повышаете уровень. Уменьшенная анимация (страница «Свечение») оставляет только баннер.",
  ["A bar for spec resources that live in an aura (for example a stacking buff). Set the spell below."] = "Полоса для ресурсов специализации, которые хранятся в эффекте (например, суммирующийся бафф). Укажите заклинание ниже.",
  ["A bar glows when the game marks the ability as about to happen (the timing comes from the game)."] = "Полоса светится, когда игра отмечает, что способность вот-вот произойдёт (время берётся из игры).",
  ["A bar that counts down to your next melee swing. Off by default; Forever only. It reads your own swings from the combat log."] = "Полоса отсчёта до вашего следующего удара в ближнем бою. По умолчанию выкл.; только Forever. Читает ваши удары из журнала боя.",
  ["A block of extra frames for every tank (or healer) in the group, in addition to the normal frames."] = "Блок дополнительных рамок для каждого танка (или лекаря) в группе, в дополнение к обычным рамкам.",
  ["A bright edge when absorbs run past full health, and when heal absorbs eat more than the health left."] = "Яркий край, когда поглощение превышает полный запас здоровья и когда поглощение исцеления съедает больше оставшегося здоровья.",
  ["A bright line where the bar is draining."] = "Яркая линия там, где полоса убывает.",
  ["A button in Blizzard's Edit Mode window that opens Phoenix Studio."] = "Кнопка в окне режима редактирования Blizzard, открывающая Phoenix Studio.",
  ["A button on the panel that cancels your oldest application, so a new one fits under the limit of five. In combat it waits until combat ends."] = "Кнопка на панели, отменяющая вашу самую старую заявку, чтобы новая уложилась в лимит из пяти. В бою ждёт окончания боя.",
  ["A button that leaves the vehicle, shown only when you can exit."] = "Кнопка выхода из транспорта, видна только когда выйти можно.",
  ["A class icon on each friend row."] = "Значок класса в каждой строке друга.",
  ["A click on a window's header opens a Phoenix list of meter types instead of cycling through them."] = "Щелчок по заголовку окна открывает список типов счётчика Phoenix вместо их перебора.",
  ["A clickable button beside quests that have a usable item (placed outside combat)."] = "Кнопка рядом с заданиями, у которых есть используемый предмет (ставится вне боя).",
  ["A cog in the title bar of every skinned window opens its Phoenix options in place."] = "Шестерёнка в заголовке каждого оформленного окна открывает его настройки Phoenix на месте.",
  ["A coloured dot for each party member targeting this enemy (shared with the party frames' enemy dots)."] = "Цветная точка за каждого члена группы, выбравшего этого противника целью (общая с точками противников на рамках группы).",
  ["A coloured glow around player, target, focus and boss frames when you have threat."] = "Цветное свечение вокруг рамок игрока, цели, фокуса и боссов, когда у вас есть угроза.",
  ["A countdown bar under the dungeon and battleground ready pop-ups (same countdown as the minimap queue eye)."] = "Полоса отсчёта под всплывающими окнами готовности подземелья и поля боя (тот же отсчёт, что у глаза очереди на миникарте).",
  ["A countdown bar while you fly. The first flight on a route is timed and remembered."] = "Полоса отсчёта во время полёта. Первый полёт по маршруту засекается и запоминается.",
  ["A dark background behind the tracker."] = "Тёмный фон за списком заданий.",
  ["A faint bar on your row showing your best pull on this boss."] = "Бледная полоса в вашей строке с вашим лучшим пулом на этом боссе.",
  ["A gold border around the enemy you are targeting."] = "Золотая рамка вокруг противника, который у вас в цели.",
  ["A green arrow on loot and rolls with a higher item level than what you wear."] = "Зелёная стрелка на добыче и розыгрышах с уровнем предмета выше надетого.",
  ["A grey cross when a cast is stopped before it finishes."] = "Серый крест, когда применение остановлено до завершения.",
  ["A hit on your target this soon after your cast counts as yours."] = "Попадание по цели в течение этого времени после вашего применения засчитывается вам.",
  ["A key that hides or shows every meter window. Empty means no key."] = "Клавиша, скрывающая или показывающая все окна счётчика. Пусто — без клавиши.",
  ["A key that resets the meter data. Empty means no key."] = "Клавиша сброса данных счётчика. Пусто — без клавиши.",
  ["A key that switches on your \"While my layer key is active\" overrides (for example bigger nameplates or a different action bar page look). Leave empty for no key."] = "Клавиша, включающая ваши настройки «Пока активна клавиша слоя» (например, крупнее индикаторы здоровья или другой вид страницы панели). Оставьте пустым — без клавиши.",
  ["A light Horde or Alliance tint behind Battle.net friends in World of Warcraft."] = "Лёгкий оттенок Орды или Альянса за друзьями Battle.net в World of Warcraft.",
  ["A line naming where arena frames, DR and queue status live."] = "Строка, указывающая, где находятся рамки арены, DR и статус очереди.",
  ["A popup grid that opens from the bin button, or a bar that is always shown along the minimap or wherever you move it."] = "Всплывающая сетка, открываемая кнопкой контейнера, или полоса, всегда видимая вдоль миникарты или там, куда вы её переместите.",
  ["A progress bar for experience, your watched reputation or honor. Data Bars owns this bar."] = "Полоса прогресса для опыта, отслеживаемой репутации или чести. Этой полосой управляют информационные панели.",
  ["A red cross when a cast is interrupted."] = "Красный крест, когда применение прервано.",
  ["A red mark on enchantable slots without an enchant."] = "Красная отметка на ячейках, которые можно зачаровать, но без чар.",
  ["A repeat inside this time is hidden when Hide repeated lines is on."] = "Повтор в пределах этого времени скрывается, когда включено «Скрывать повторяющиеся строки».",
  ["A right click on the header opens a list of fights (current, overall, last saved) instead of cycling."] = "Щелчок правой кнопкой по заголовку открывает список боёв (текущий, общий, последний сохранённый) вместо перебора.",
  ["A ring around your mouse cursor, so you never lose it in a busy fight."] = "Кольцо вокруг курсора мыши, чтобы не терять его в суматохе боя.",
  ["A row of small buttons (Say, Party, Instance, Raid, Guild, Officer, Whisper, 1, 2) that open the chat box on that channel."] = "Ряд маленьких кнопок (Сказать, Группа, Подземелье, Рейд, Гильдия, Офицер, Шепот, 1, 2), открывающих чат на этом канале.",
  ["A search box in the popup that narrows the buttons by name."] = "Поле поиска во всплывающем окне, фильтрующее кнопки по названию.",
  ["A small badge with the number of new errors this session; click it to open the viewer."] = "Маленький значок с числом новых ошибок за сеанс; щёлкните, чтобы открыть просмотр.",
  ["A small clock for the current fight. It is the one shared timer: the Embers title bar and the Mythic+ card read the same clock."] = "Небольшие часы текущего боя. Это общий таймер: его же читают заголовок Embers и карточка Эпохального+.",
  ["A small dot in the middle of the ring."] = "Маленькая точка в центре кольца.",
  ["A small frame for each enemy pet (click to target, right-click to focus)."] = "Маленькая рамка для каждого питомца противника (щелчок — цель, правый щелчок — фокус).",
  ["A small list of the next boss abilities and their times during a boss fight. Move it in Studio."] = "Небольшой список следующих способностей босса и их времени во время боя с боссом. Перемещается в Studio.",
  ["A small mark on your focus."] = "Небольшая отметка на вашем фокусе.",
  ["A small popup the first time a new error happens (repeats are only counted)."] = "Небольшое окно при первом появлении новой ошибки (повторы только подсчитываются).",
  ["A small read-only Phoenix panel inside Blizzard's conquest frame with your title progress and conquest."] = "Небольшая панель Phoenix только для чтения в окне завоевания Blizzard с прогрессом звания и завоеванием.",
  ["A soft glow around reminder icons."] = "Мягкое свечение вокруг значков напоминаний.",
  ["A soft shadow under Phoenix window text."] = "Мягкая тень под текстом окон Phoenix.",
  ["A spell shown in the cooldown manager's Essential or Utility rows is hidden on your bars. Off while the cooldown manager hides icons that are on your bars (pick one)."] = "Заклинание, показанное в рядах «Важное» или «Вспомогательное» менеджера восстановления, скрывается на ваших панелях. Выкл., пока менеджер восстановления скрывает значки, которые есть на ваших панелях (выберите одно).",
  ["A starting look for size, spacing and icon side. Every part can still be changed on its own below."] = "Начальный вид для размера, отступов и стороны значка. Каждую часть всё равно можно изменить отдельно ниже.",
  ["A strip of recent casts for arena 1."] = "Полоса недавних применений для арены 1.",
  ["A strip of recent casts for arena 2."] = "Полоса недавних применений для арены 2.",
  ["A strip of recent casts for arena 3."] = "Полоса недавних применений для арены 3.",
  ["A strip of recent casts for focus."] = "Полоса недавних применений для фокуса.",
  ["A strip of recent casts for party 1."] = "Полоса недавних применений для группы 1.",
  ["A strip of recent casts for party 2."] = "Полоса недавних применений для группы 2.",
  ["A strip of recent casts for party 3."] = "Полоса недавних применений для группы 3.",
  ["A strip of recent casts for party 4."] = "Полоса недавних применений для группы 4.",
  ["A strip of recent casts for target."] = "Полоса недавних применений для цели.",
  ["A strip of recent casts for you."] = "Полоса ваших недавних применений.",
  ["A thin accent border on the friends frame and an accent line under the open tab."] = "Тонкая акцентная рамка на окне друзей и акцентная линия под открытой вкладкой.",
  ["A thin accent line at the right edge shows where you are while scrolled."] = "Тонкая акцентная линия у правого края показывает позицию при прокрутке.",
  ["A thin accent-coloured line under the health bar."] = "Тонкая линия цвета акцента под полосой здоровья.",
  ["A thin dark border around each icon."] = "Тонкая тёмная рамка вокруг каждого значка.",
  ["A white edge when a shield is bigger than the missing health, and a red edge when a heal absorb is bigger than the current health."] = "Белый край, когда щит больше недостающего здоровья, и красный край, когда поглощение исцеления больше текущего здоровья.",
  ["A/B report"] = "Отчёт A/B",
  ["Abilities listed"] = "Перечисленные способности",
  ["Abilities the game only estimates show a ~ until their time is firm."] = "Способности, время которых игра лишь оценивает, показывают ~, пока время не уточнится.",
  ["Ability icon"] = "Значок способности",
  ["Ability substitutions"] = "Замены способностей",
  ["Accent colour"] = "Цвет акцента",
  ["Accent line"] = "Акцентная линия",
  ["Accept group invites from friends"] = "Принимать приглашения в группу от друзей",
  ["Accept group invites from guild"] = "Принимать приглашения в группу от гильдии",
  ["Accept invites from friends"] = "Принимать приглашения от друзей",
  ["Accept role checks for me"] = "Принимать проверку ролей за меня",
  ["Accepts a dungeon or raid finder role check with the roles you have set. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "Принимает проверку ролей поиска подземелий или рейдов с заданными вами ролями. Blizzard выполняет это окно защищённым кодом; помощь аддона здесь изредка может вызвать сообщение «действие интерфейса заблокировано». По умолчанию включено, потому что вы так выбрали; выключите, если когда-нибудь увидите это.",
  ["Accepts and turns in quests with at most one reward choice. Hold the pause key to read the quest."] = "Принимает и сдаёт задания, где не больше одного варианта награды. Удерживайте клавишу паузы, чтобы прочитать задание.",
  ["Accepts group invites from WoW and Battle.net friends. Never while you are queued or in combat."] = "Принимает приглашения в группу от друзей WoW и Battle.net. Никогда в очереди или в бою.",
  ["Accepts group invites from friends, Battle.net friends and guild members. While the Friends module is on, its own per-source switches decide instead."] = "Принимает приглашения в группу от друзей, друзей Battle.net и членов гильдии. Когда включён модуль «Друзья», решают его собственные переключатели по источникам.",
  ["Accepts group invites from guild members. Never while you are queued or in combat."] = "Принимает приглашения в группу от членов гильдии. Никогда в очереди или в бою.",
  ["Achievements"] = "Достижения",
  ["Action bar 1"] = "Панель команд 1",
  ["Action bar 10"] = "Панель команд 10",
  ["Action bar 2"] = "Панель команд 2",
  ["Action bar 3"] = "Панель команд 3",
  ["Action bar 4"] = "Панель команд 4",
  ["Action bar 5"] = "Панель команд 5",
  ["Action bar 6"] = "Панель команд 6",
  ["Action bar 7"] = "Панель команд 7",
  ["Action bar 8"] = "Панель команд 8",
  ["Action bar 9"] = "Панель команд 9",
  ["Action bars"] = "Панели команд",
  ["Action bars: when another addon does this"] = "Панели команд: когда это делает другой аддон",
  ["Action button tooltips"] = "Подсказки кнопок действий",
  ["Action status text"] = "Текст состояния действия",
  ["Actions can only be dragged off with the pick-up modifier (Shift by default)."] = "Действия можно стащить с панели только с модификатором подбора (по умолчанию Shift).",
  ["Activity on the row"] = "Активность в строке",
  ["Add group size"] = "Добавлять размер группы",
  ["Add on-use trinkets"] = "Добавлять аксессуары с эффектом при использовании",
  ["Add text slot: one line each, \"tag @ POINT x y size\" (for example health:percent @ TOPRIGHT 0 10 14)."] = "Добавить текстовый слот: по строке на каждый, \"tag @ POINT x y size\" (например, health:percent @ TOPRIGHT 0 10 14).",
  ["Add your own character name to reports. Other players' names are never collected."] = "Добавлять имя вашего персонажа в отчёты. Имена других игроков никогда не собираются.",
  ["Add, remove and reorder columns. Column IDs: name, spec, damage, healing, kb, deaths, hk, rating, ratingChange, mmrBefore, mmrAfter, honor, plus any column another addon adds."] = "Добавляйте, удаляйте и переставляйте столбцы. ID столбцов: name, spec, damage, healing, kb, deaths, hk, rating, ratingChange, mmrBefore, mmrAfter, honor, а также любой столбец, добавленный другим аддоном.",
  ["AddOn list"] = "Список аддонов",
  ["Addon compartment"] = "Отсек аддонов",
  ["Addon sections in the viewer open collapsed; click a section header to expand it."] = "Разделы аддонов в окне просмотра открываются свёрнутыми; щёлкните заголовок раздела, чтобы развернуть.",
  ["Adds ID lines (spell, item, NPC, quest and 23 more kinds) to tooltips. Phoenix is the only place IDs are added."] = "Добавляет в подсказки строки ID (заклинание, предмет, NPC, задание и ещё 23 вида). Phoenix — единственное место, где добавляются ID.",
  ["Adds Phoenix's own emoji: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:."] = "Добавляет собственные смайлы Phoenix: :smile: :grin: :laugh: :wink: :sad: :cry: :angry: :cool: :wow: :think: :sleep: :gg: :heart: :fire: :thumbsup: :dead:.",
  ["Adds a Phoenix UI button above the Escape menu."] = "Добавляет кнопку Phoenix UI над меню Escape.",
  ["Adds a Train all button to the class trainer."] = "Добавляет кнопку «Обучить всему» у наставника класса.",
  ["Adds a glow around the frame while the class icon shows an aura."] = "Добавляет свечение вокруг рамки, пока значок класса показывает эффект.",
  ["Adds channelled spells to the strip."] = "Добавляет на полосу поддерживаемые заклинания.",
  ["Adds each row's share of the total when the game shows the numbers."] = "Добавляет долю каждой строки от общего, когда игра показывает числа.",
  ["Adds gear from your bags as commented lines, so Raidbots Top Gear can compare it."] = "Добавляет снаряжение из сумок закомментированными строками, чтобы Raidbots Top Gear мог его сравнить.",
  ["Adds guild name and rank to player tooltips."] = "Добавляет название гильдии и звание в подсказки игроков.",
  ["Adds kills, wipes and your best time to the tooltip of a boss you have stats for."] = "Добавляет убийства, вайпы и ваше лучшее время в подсказку босса, по которому есть статистика.",
  ["Adds roles in fixed order, class-coloured counts, age, leader score and decline memory to the group tooltip."] = "Добавляет в подсказку группы роли в фиксированном порядке, количество по цветам классов, давность, рейтинг лидера и память об отказах.",
  ["Adds the Phoenix score or item-level difference to item tooltips."] = "Добавляет в подсказки предметов рейтинг Phoenix или разницу уровня предмета.",
  ["Adds the enemy forces of the enemies you are fighting to the forces line."] = "Добавляет к строке сил силы противника тех врагов, с которыми вы сражаетесь.",
  ["Adds the highest key the player finished this season next to the score."] = "Добавляет рядом с рейтингом самый высокий ключ, пройденный игроком в этом сезоне.",
  ["Adds the leader's best timed key level in that dungeon next to the score."] = "Добавляет рядом с рейтингом лучший пройденный вовремя уровень ключа лидера в этом подземелье.",
  ["Adds the per-second figure to saved segments."] = "Добавляет к сохранённым сегментам показатель в секунду.",
  ["Adds the player's Mythic+ score, coloured by your M+ score colour setting."] = "Добавляет рейтинг Эпохального+ игрока, окрашенный по вашей настройке цвета рейтинга M+.",
  ["Adds the raid size to the difficulty, such as 25H."] = "Добавляет размер рейда к сложности, например 25H.",
  ["Adds your equipped trinkets that have a use effect to the item bars."] = "Добавляет на полосы предметов надетые аксессуары с эффектом при использовании.",
  ["Advanced: macro conditions that show or hide bar 1, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 1, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 10, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 10, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 2, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 2, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 3, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 3, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 4, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 4, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 5, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 5, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 6, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 6, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 7, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 7, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 8, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 8, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Advanced: macro conditions that show or hide bar 9, e.g. [combat] show; hide. When set, this replaces the where-to-show choice."] = "Дополнительно: макроусловия, показывающие или скрывающие панель 9, например [combat] show; hide. Если заданы, заменяют выбор «где показывать».",
  ["Adventure Guide"] = "Путеводитель по приключениям",
  ["After a boss, sends the top line through Phoenix announcements (where it goes is set on the Announcements page)."] = "После босса отправляет верхнюю строку через объявления Phoenix (куда — задаётся на странице «Объявления»).",
  ["After a ready check, prints who was not ready or did not answer."] = "После проверки готовности выводит, кто не был готов или не ответил.",
  ["After a restore, make the Phoenix Edit Mode layout the active one."] = "После восстановления сделать макет режима редактирования Phoenix активным.",
  ["After a run"] = "После забега",
  ["After a talent or specialization change, lists tracked cooldowns that are on none of your action bars."] = "После смены талантов или специализации перечисляет отслеживаемые восстановления, которых нет ни на одной панели команд.",
  ["After an enemy is seen dispelling, shows their dispel with its cooldown. Only dispels the game reports plainly are seen."] = "Когда замечено, что противник рассеивает, показывает его рассеивание с восстановлением. Видны только рассеивания, о которых игра сообщает явно.",
  ["After an enemy's cast is interrupted, the plate shows \"Interrupted by <name>\" for a moment."] = "Когда применение противника прервано, индикатор на мгновение показывает «Прервано: <имя>».",
  ["After-match card"] = "Карточка после матча",
  ["Aggro border"] = "Рамка агро",
  ["Alert again after (s)"] = "Повторить оповещение через (с)",
  ["Alert sound"] = "Звук оповещения",
  ["Alert toasts"] = "Всплывающие оповещения",
  ["Alerts and toasts"] = "Оповещения и уведомления",
  ["All tracked quests, only those in progress, or only those ready to turn in."] = "Все отслеживаемые задания, только выполняемые или только готовые к сдаче.",
  ["Alphabetical, or the order you drag them into (Shift-click the bin button to edit)."] = "По алфавиту или в порядке перетаскивания (Shift-щелчок по кнопке контейнера для правки).",
  ["Also keeps errors from other addons and Blizzard's code in the viewer, on this PC only. They never join Phoenix's reports unless you allow it below."] = "Также хранит ошибки других аддонов и кода Blizzard в окне просмотра, только на этом ПК. Они никогда не попадают в отчёты Phoenix, если вы не разрешите ниже.",
  ["Also narrow Blizzard's search: minimum rating"] = "Также сузить поиск Blizzard: минимальный рейтинг",
  ["Also narrow Blizzard's search: needs my role"] = "Также сузить поиск Blizzard: нужна моя роль",
  ["Also prints the rating change in your chat window after each rated match."] = "Также выводит изменение рейтинга в окно чата после каждого рейтингового матча.",
  ["Also shows a dot for each boss targeting this member."] = "Также показывает точку за каждого босса, выбравшего этого участника целью.",
  ["Also shows the addons listed in Blizzard's addon compartment as buttons in the bin."] = "Также показывает аддоны из отсека аддонов Blizzard как кнопки в контейнере.",
  ["Alt+click Phoenix UI in the minimap addon menu to show or clear the Cast History test strip."] = "Alt+щелчок по Phoenix UI в меню аддонов миникарты показывает или убирает тестовую полосу Cast History.",
  ["Alt+click in the addon menu"] = "Alt+щелчок в меню аддонов",
  ["Alternate power bar"] = "Полоса альтернативной энергии",
  ["Always on the minimap"] = "Всегда на миникарте",
  ["Always show me"] = "Всегда показывать меня",
  ["An accent dot on communities with unread messages."] = "Акцентная точка на сообществах с непрочитанными сообщениями.",
  ["An accent frame on transmog slots with an unsaved change."] = "Акцентная рамка на ячейках трансмогрификации с несохранённым изменением.",
  ["An accent glow on Great Vault slots you have unlocked."] = "Акцентное свечение на открытых вами ячейках Великого хранилища.",
  ["An accent line under the open tab."] = "Акцентная линия под открытой вкладкой.",
  ["An accent ring on chosen talents, a dim ring on talents you can still pick."] = "Акцентное кольцо на выбранных талантах, тусклое — на талантах, которые ещё можно взять.",
  ["An essential or utility cooldown that is on one of your shown action bars is left out of these rows, so it appears once."] = "Важное или вспомогательное восстановление, которое есть на одной из показанных панелей команд, не включается в эти ряды, чтобы появляться один раз.",
