  ["As a tank, plates another tank in your group is holding get their own colour instead of the danger colour."] = "Для танка: индикаторы противников, которых держит другой танк вашей группы, получают свой цвет вместо цвета опасности.",
  ["Ascent"] = "Ascent",
  ["Asks the game to show only DR categories your own spells can cause (needs DR tracking on). Your old value comes back when off."] = "Просит игру показывать только категории DR, которые могут вызывать ваши заклинания (нужно отслеживание DR). Прежнее значение возвращается при выключении.",
  ["Asks whether to leave the group when a Dungeon Finder run is complete. Never leaves on its own."] = "Спрашивает, покинуть ли группу, когда забег в поиске подземелий завершён. Сам никогда не уходит.",
