  ["Bars use the game's colour for how dangerous each ability is. Off: every bar uses the normal colour."] = "Полосы используют цвет игры, обозначающий опасность способности. Выкл.: все полосы обычного цвета.",
  ["Bars with nothing to show (no aura, no totem slots, no class resource) take no room; the bars below move up."] = "Полосы без содержимого (нет эффекта, ячеек тотемов, ресурса класса) не занимают места; нижние полосы поднимаются.",
