  ["Difficulty position"] = "Положение сложности",
  ["Digits after the decimal point."] = "Цифр после запятой.",
  ["Dim buttons on cooldown"] = "Затемнять кнопки на восстановлении",
  ["Dim filtered groups"] = "Затемнять отфильтрованные группы",
  ["Dim strength"] = "Сила затемнения",
  ["Dim uncollected"] = "Затемнять несобранное",
  ["Dim unusable items"] = "Затемнять непригодные предметы",
  ["Dims Blizzard rows your filter or minimum rating rejects. Blizzard's list itself is never changed."] = "Затемняет строки Blizzard, которые отвергает ваш фильтр или минимальный рейтинг. Сам список Blizzard никогда не меняется.",
  ["Direction"] = "Направление",
  ["Direction from enemy 1 to enemy 3."] = "Направление от противника 1 к противнику 3.",
