  ["Direction the row of buttons grows from the corner."] = "Направление роста ряда кнопок от угла.",
  ["Dispel highlight"] = "Подсветка рассеивания",
  ["Dispel highlight colour"] = "Цвет подсветки рассеивания",
  ["Dispel highlight shows"] = "Подсветка рассеивания показывает",
  ["Dispel highlight style"] = "Стиль подсветки рассеивания",
  ["Dispel icon size"] = "Размер значка рассеивания",
  ["Dispel icon size."] = "Размер значка рассеивания.",
  ["Dispel tint strength"] = "Сила оттенка рассеивания",
  ["Dispel tracker"] = "Отслеживание рассеиваний",
  ["Distance labels"] = "Метки расстояния",
  ["Do not share repeatable quests"] = "Не передавать повторяемые задания",
  ["Dock several meter windows together under one Studio mover (Embers dock), or leave them free."] = "Объединять несколько окон счётчика под одним перемещателем Studio (стыковка Embers) или оставить их свободными.",
  ["Docked above the group finder: your roles at a glance, with locks on roles your class cannot play."] = "Пристыковано над поиском групп: ваши роли с первого взгляда, с замками на ролях, недоступных вашему классу.",
  ["Docked inside the M+ block or as its own widget (also shown in raid boss fights)."] = "Внутри блока M+ или отдельным виджетом (также показывается в боях с боссами рейда).",
  ["Docked panel with Phoenix's sorted list of the groups your filter keeps and the why-hidden line."] = "Пристыкованная панель с отсортированным списком Phoenix групп, которые оставляет ваш фильтр, и строкой «почему скрыто».",
  ["Docked window gap"] = "Зазор стыковки окон",
  ["Docks the Mythic+ block at the top of the Phoenix quest tracker, or shows it as its own movable window. When the Phoenix tracker is off it always uses its own window."] = "Пристыковывает блок Эпохального+ к верху списка заданий Phoenix или показывает его отдельным перемещаемым окном. Когда список Phoenix выключен, всегда использует отдельное окно.",
  ["Docks the bar on the minimap edge the bar grows along, or lets you place it with the Studio mover."] = "Пристыковывает полосу к краю миникарты, вдоль которого она растёт, или позволяет разместить её перемещателем Studio.",
  ["Does not repeat the exact same announcement within 5 seconds."] = "Не повторяет одно и то же объявление в течение 5 секунд.",
  ["Double-click a group (in Blizzard's list or Phoenix's) to open its sign-up. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "Двойной щелчок по группе (в списке Blizzard или Phoenix) открывает запись в неё. Blizzard выполняет это окно защищённым кодом; помощь аддона здесь изредка может вызвать сообщение «действие интерфейса заблокировано». По умолчанию включено, потому что вы так выбрали; выключите, если когда-нибудь увидите это.",
  ["Double-click a group to sign up"] = "Двойной щелчок по группе для записи",
  ["Drag Blizzard windows (character, map, bags, talents and about 50 more) by their title. Ctrl + mouse wheel scales, Shift + right-click resets."] = "Перетаскивайте окна Blizzard (персонаж, карта, сумки, таланты и ещё около 50) за заголовок. Ctrl + колесо мыши масштабирует, Shift + правый щелчок сбрасывает.",
  ["Drag a scoreboard header onto another to change the column order."] = "Перетащите заголовок таблицы результатов на другой, чтобы изменить порядок столбцов.",
  ["Drag scoreboard headers"] = "Перетаскивать заголовки таблицы результатов",
  ["Drag the whole selection"] = "Перетаскивать всё выделение",
  ["Dragged elements snap to the Studio grid."] = "Перетаскиваемые элементы привязываются к сетке Studio.",
  ["Draw the pixel grid while Studio is open."] = "Показывать пиксельную сетку, пока открыт Studio.",
  ["Draw the screen's centre lines while Studio is open."] = "Показывать центральные линии экрана, пока открыт Studio.",
  ["Draws a line from each attached element to the element it is attached to while Studio is open."] = "Пока открыт Studio, рисует линию от каждого прикреплённого элемента к элементу, к которому он прикреплён.",
  ["Draws a thin line at the execute percent."] = "Рисует тонкую линию на проценте добивания.",
  ["Draws each button on a Phoenix tile with an icon mask; turn off to keep each addon's own look."] = "Рисует каждую кнопку на плитке Phoenix с маской значка; выключите, чтобы сохранить вид каждого аддона.",
  ["Draws the bright moving edge on the cooldown swipe."] = "Рисует яркий движущийся край на заливке восстановления.",
  ["Draws the frame of buttons that hold no action."] = "Рисует рамку кнопок без действия.",
  ["Draws the pull, break and key countdown that Raid Tools runs (yours or anyone's in the group)."] = "Рисует отсчёт пула, перерыва и ключа, который запускает Raid Tools (ваш или любого в группе).",
