  ["Durability figure"] = "Показатель прочности",
  ["Durability on slots"] = "Прочность на ячейках",
  ["Durability percent on damaged items."] = "Процент прочности на повреждённых предметах.",
  ["Durability threshold (%)"] = "Порог прочности (%)",
  ["EU, US, KR, TW or CN for Battle.net friends."] = "EU, US, KR, TW или CN для друзей Battle.net.",
  ["Each bracket's rating, season best and this week's record."] = "Рейтинг каждой категории, лучший за сезон и результаты этой недели.",
  ["Each specialization can keep its own block list for every bar (save one with /pui dbspec save). Specs without a saved set use the normal lists."] = "Каждая специализация может хранить свой список блокировки для каждой панели (сохраните его через /pui dbspec save). Специализации без сохранённого набора используют обычные списки.",
  ["Each specialization can use its own profile. When you change spec, Phoenix switches to that profile (after combat). Content profiles for raid, arena or Mythic+ still apply on top."] = "Каждая специализация может использовать свой профиль. При смене специализации Phoenix переключается на этот профиль (после боя). Профили контента для рейда, арены или Эпохального+ по-прежнему применяются поверх.",
  ["Each time you save in Edit Mode, Phoenix keeps a copy of the active layout in this profile; /pui editmode restore puts it back as a layout named Phoenix."] = "Каждый раз при сохранении в режиме редактирования Phoenix хранит копию активного макета в этом профиле; /pui editmode restore возвращает его как макет с именем Phoenix.",
  ["Earned achievements get an accent stripe."] = "Полученные достижения получают акцентную полосу.",
  ["Earned colour"] = "Цвет полученного",
  ["Ebon Might"] = "Эбеновая мощь",
  ["Edit Mode"] = "Режим редактирования",
  ["Edit and search boxes"] = "Поля ввода и поиска",
  ["Effects that eat healing, drawn in red inside the health fill."] = "Эффекты, поглощающие исцеление, рисуются красным внутри заливки здоровья.",
  ["Eight buttons that put a raid marker on your target."] = "Восемь кнопок, ставящих рейдовую метку на вашу цель.",
  ["Eight secure buttons that place or remove a world marker, plus clear all. Changes wait until combat ends."] = "Восемь защищённых кнопок для установки или снятия метки на местности, плюс «очистить всё». Изменения ждут конца боя.",
  ["Element names"] = "Названия элементов",
  ["Elite and rare icon"] = "Значок элиты и редкого",
  ["Ember (portrait, flat bars, thick power), Glass (rounded, thin power, class icon), Blizzard-like or Classic-like. Each part of the look can also be changed on its own below."] = "Ember (портрет, плоские полосы, толстая энергия), Glass (скругления, тонкая энергия, значок класса), как у Blizzard или как в Classic. Каждую часть вида можно изменить отдельно ниже.",
  ["Embers"] = "Embers",
  ["Embers dock"] = "Стыковка Embers",
  ["Embers window 1"] = "Окно Embers 1",
  ["Embers window 2"] = "Окно Embers 2",
  ["Embers window 3"] = "Окно Embers 3",
  ["Embers window 4"] = "Окно Embers 4",
  ["Embers' spell breakdown gets a Casts button that shows that player's recent casts (you and your party)."] = "Разбивка заклинаний Embers получает кнопку «Применения», показывающую недавние применения игрока (вас и вашей группы).",
  ["Emoji"] = "Смайлы",
  ["Emoji size"] = "Размер смайлов",
  ["Emoji suggestions while typing"] = "Подсказки смайлов при наборе",
  ["Empower stage marks"] = "Отметки стадий усиления",
  ["Empowered spells show \"hold\" until released."] = "Усиливаемые заклинания показывают «держите» до отпускания.",
  ["Empty uses \"%a %s %c\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "Пусто — \"%a %s %c\". Токены: %a количество, %s заклинание или предмет, %c число, %e событие, %t добавка (сокрушительный, скользящий).",
  ["Empty uses \"%e\". Tokens: %a amount, %s spell or item, %c count, %e event, %t trailer (crushing, glancing)."] = "Пусто — \"%e\". Токены: %a количество, %s заклинание или предмет, %c число, %e событие, %t добавка (сокрушительный, скользящий).",
