  ["Fades an enemy's frame while your range spell cannot reach them."] = "Приглушает рамку противника, пока ваше заклинание дальности не достаёт до него.",
  ["Fades frames of members out of your range."] = "Приглушает рамки участников вне вашей досягаемости.",
  ["Fades out Blizzard's addon compartment. It comes back when you turn this off or the module off."] = "Скрывает отсек аддонов Blizzard. Он возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's blizzard instance difficulty badge. It comes back when you turn this off or the module off."] = "Скрывает значок сложности подземелья Blizzard. Он возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's calendar button. It comes back when you turn this off or the module off."] = "Скрывает кнопку календаря Blizzard. Она возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's crafting order icon. It comes back when you turn this off or the module off."] = "Скрывает значок заказов на изготовление Blizzard. Он возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's expansion summary button. It comes back when you turn this off or the module off."] = "Скрывает кнопку сводки дополнения Blizzard. Она возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's mail icon. It comes back when you turn this off or the module off."] = "Скрывает значок почты Blizzard. Он возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's minimap border, zone bar and compass ring; Phoenix shows the zone itself."] = "Скрывает рамку миникарты Blizzard, полосу зоны и кольцо компаса; Phoenix сам показывает зону.",
  ["Fades out Blizzard's tracking button. It comes back when you turn this off or the module off."] = "Скрывает кнопку отслеживания Blizzard. Она возвращается при выключении этой настройки или модуля.",
  ["Fades out Blizzard's zoom buttons. It comes back when you turn this off or the module off."] = "Скрывает кнопки масштаба Blizzard. Они возвращаются при выключении этой настройки или модуля.",
  ["Fades target, focus and boss frames that are out of range (when the game can tell)."] = "Приглушает рамки цели, фокуса и боссов вне досягаемости (когда игра это сообщает).",
  ["Fades the Blizzard objective tracker while a key runs."] = "Приглушает список целей Blizzard во время ключа.",
  ["Fights in history"] = "Боёв в истории",
