  ["Hide the extra action button's art"] = "Скрыть оформление кнопки особого действия",
  ["Hide the name while casting"] = "Скрывать имя во время произнесения",
  ["Hide the zone ability art"] = "Скрыть оформление способности зоны",
  ["Hide tracking button"] = "Скрыть кнопку отслеживания",
  ["Hide tutorials"] = "Скрыть обучающие подсказки",
  ["Hide zoom buttons"] = "Скрыть кнопки масштаба",
  ["Hides Sated, Exhaustion, Forbearance and similar lockouts from the debuff icons."] = "Скрывает «Пресыщение», «Изнеможение», «Воздержанность» и подобные блокировки из значков дебаффов.",
  ["Hides a buff here when the Cooldown Manager's tracked buff bars already show it, so nothing appears twice."] = "Скрывает здесь бафф, если его уже показывают отслеживаемые полосы баффов менеджера восстановления, чтобы ничего не повторялось.",
  ["Hides a line when the same player repeats the same text within a short time."] = "Скрывает строку, когда тот же игрок повторяет тот же текст за короткое время.",
  ["Hides the big boss-loot and level-up banners."] = "Скрывает большие баннеры добычи с боссов и повышения уровня.",
  ["Hides the default party and raid frames while Phoenix group frames are on."] = "Скрывает стандартные рамки группы и рейда, пока включены рамки группы Phoenix.",
  ["Hides the default pet bar while the Phoenix one is on."] = "Скрывает стандартную панель питомца, пока включена панель Phoenix.",
  ["Hides the default player cast bar while the Phoenix cast bar is shown."] = "Скрывает стандартную полосу заклинаний игрока, пока показана полоса Phoenix.",
  ["Hides the default stance bar while the Phoenix one is on."] = "Скрывает стандартную панель стоек, пока включена панель Phoenix.",
  ["Hides the enemy's name while it casts so the cast bar is easier to read."] = "Скрывает имя противника во время произнесения, чтобы полосу было легче читать.",
  ["Hides the expression lines; the list, count and sort stay. Sorting and filters are shared with the full view."] = "Скрывает строки выражения; список, счётчик и сортировка остаются. Сортировка и фильтры общие с полным видом.",
  ["Hides the game's arena frames while Phoenix shows its own (never moved or changed; shown again when this is off)."] = "Скрывает рамки арены игры, пока Phoenix показывает свои (никогда не перемещаются и не меняются; снова видны при выключении).",
  ["Hides the gold ring and dark disc minimap buttons draw; given back when skinning is off."] = "Скрывает золотое кольцо и тёмный диск, которые рисуют кнопки миникарты; возвращаются при выключении оформления.",
  ["Hides the scroll bar of Blizzard's meter windows; the mouse wheel still scrolls."] = "Скрывает полосу прокрутки окон счётчика Blizzard; колесо мыши по-прежнему прокручивает.",
  ["High power colour"] = "Цвет высокой энергии",
  ["High power colour for the threshold colouring."] = "Цвет высокой энергии для окраски по порогам.",
  ["High power from (%)"] = "Высокая энергия от (%)",
  ["Highest first"] = "Сначала наибольшие",
  ["Highlight keywords"] = "Выделять ключевые слова",
  ["Highlight the plate under the mouse"] = "Подсвечивать индикатор под мышью",
  ["Highlight you"] = "Выделять вас",
  ["Highlight your team"] = "Выделять вашу команду",
  ["Highlights items you just received."] = "Подсвечивает только что полученные предметы.",
  ["Highlights members carrying a debuff that can be dispelled."] = "Подсвечивает участников с дебаффом, который можно рассеять.",
  ["History rows"] = "Строк истории",
  ["Hits from the same spell close together become one line (Rend x5)."] = "Попадания одного заклинания подряд объединяются в одну строку (Кровопускание x5).",
  ["Hits you avoid (dodge, parry, absorb...)"] = "Избегнутые удары (уклонение, парирование, поглощение...)",
  ["Hits you avoid (dodge, parry, absorb...): area"] = "Избегнутые удары (уклонение, парирование, поглощение...): область",
  ["Hits you avoid (dodge, parry, absorb...): colour"] = "Избегнутые удары (уклонение, парирование, поглощение...): цвет",
  ["Hits you avoid (dodge, parry, absorb...): message"] = "Избегнутые удары (уклонение, парирование, поглощение...): сообщение",
  ["Hits you avoid (dodge, parry, absorb...): sound"] = "Избегнутые удары (уклонение, парирование, поглощение...): звук",
  ["Hold Ctrl and scroll over a window title to scale it."] = "Удерживайте Ctrl и прокручивайте над заголовком окна, чтобы масштабировать его.",
  ["Hold this key to read a quest instead of auto accepting or turning it in."] = "Удерживайте эту клавишу, чтобы прочитать задание вместо автопринятия или сдачи.",
  ["Hold: the layer is on only while the key is down. Toggle: press once for on, again for off."] = "Удержание: слой включён, только пока клавиша нажата. Переключение: нажмите раз — вкл., ещё раз — выкл.",
  ["Holy power"] = "Энергия Света",
  ["Honor"] = "Честь",
  ["Honor colour"] = "Цвет чести",
  ["Honor: area"] = "Честь: область",
  ["Honor: colour"] = "Честь: цвет",
  ["Honor: message"] = "Честь: сообщение",
  ["Honor: sound"] = "Честь: звук",
  ["Hostile colour"] = "Цвет враждебного",
  ["Housing"] = "Жилище",
  ["Housing controls"] = "Управление жилищем",
  ["Hover colour"] = "Цвет наведения",
  ["Hover strength"] = "Сила наведения",
  ["Hovercast keys"] = "Клавиши применения при наведении",
  ["Hovering a row opens the spell breakdown beside the window, on the side with more room."] = "Наведение на строку открывает разбивку заклинаний рядом с окном, со стороны, где больше места.",
  ["How Phoenix keeps the game's plate out of sight under its own. It always comes back when Phoenix lets the plate go."] = "Как Phoenix прячет индикатор игры под своим. Он всегда возвращается, когда Phoenix отпускает индикатор.",
  ["How a button glows when the game highlights the spell (a proc)."] = "Как светится кнопка, когда игра подсвечивает заклинание (срабатывание).",
  ["How a button shows that its target is out of range."] = "Как кнопка показывает, что цель вне досягаемости.",
  ["How a dispellable debuff is shown on the frame."] = "Как рассеиваемый дебафф показывается на рамке.",
  ["How amounts are written. Numbers the game hides in combat always use the game's own short format."] = "Как записываются количества. Числа, скрываемые игрой в бою, всегда в коротком формате игры.",
  ["How class icons on friend rows look."] = "Как выглядят значки классов в строках друзей.",
  ["How close (in UI pixels) an edge must come before it snaps."] = "Насколько близко (в пикселях интерфейса) должен подойти край для привязки.",
  ["How dark the cooldown swipe is."] = "Насколько темна заливка восстановления.",
  ["How dark the screen gets behind the movers."] = "Насколько темнеет экран за перемещателями.",
  ["How each ID line is labelled."] = "Как подписана каждая строка ID.",
  ["How enemy forces are written."] = "Как записываются силы противника.",
  ["How faded an out-of-range enemy is."] = "Насколько приглушён противник вне досягаемости.",
  ["How faded app-only friends are on Blizzard's list while hidden."] = "Насколько приглушены друзья только из приложения в списке Blizzard, пока скрыты.",
  ["How faded the frame of an enemy who left is."] = "Насколько приглушена рамка ушедшего противника.",
  ["How far away plates appear; 0 keeps the game's value."] = "На каком расстоянии появляются индикаторы; 0 — значение игры.",
  ["How far lines travel."] = "Как далеко улетают строки.",
  ["How fast pulsing and flashing glows animate."] = "Как быстро анимируются пульсирующее и мигающее свечение.",
  ["How gold is written in the footer."] = "Как записывается золото в нижней строке.",
  ["How icons are ordered."] = "Как упорядочены значки.",
  ["How large numbers look everywhere in Phoenix (meters, data bars, unit text, combat text)."] = "Как выглядят большие числа везде в Phoenix (счётчики, информационные панели, текст юнитов, текст боя).",
  ["How lines move."] = "Как движутся строки.",
  ["How long Spark waits to merge repeated hits."] = "Сколько Spark ждёт, чтобы объединить повторные попадания.",
  ["How long a dungeon or raid finder invite stays open, used for the queue-pop countdown everywhere (minimap queue eye, queue popup). Battleground invites use the game's own expiry."] = "Сколько остаётся открытым приглашение поиска подземелий или рейдов; используется для отсчёта приглашения из очереди везде (глаз очереди на миникарте, окно очереди). Приглашения на поля боя используют срок самой игры.",
  ["How long a line stays."] = "Как долго держится строка.",
  ["How long an icon takes to move one place."] = "Как долго значок перемещается на одно место.",
  ["How long the bar stays after a cast ends, in the interrupted or finished colour; 0 hides it at once."] = "Как долго полоса остаётся после окончания применения цветом прерывания или завершения; 0 скрывает сразу.",
  ["How long the final time stays on screen after a fight."] = "Как долго итоговое время остаётся на экране после боя.",
  ["How long the flash and tag stay."] = "Как долго держатся вспышка и метка.",
  ["How long the line stays (seconds)."] = "Как долго держится строка (секунды).",
  ["How long the notice stays."] = "Как долго держится уведомление.",
  ["How long the question stays on screen before it closes by itself."] = "Как долго вопрос остаётся на экране, прежде чем закроется сам.",
  ["How long the ready pop-up ignores clicks."] = "Как долго окно готовности игнорирует щелчки.",
  ["How many bosses the stats window lists (most recent first)."] = "Сколько боссов перечисляет окно статистики (сначала последние).",
  ["How many buttons bar 1 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 1 (страница действий вмещает 12).",
  ["How many buttons bar 10 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 10 (страница действий вмещает 12).",
  ["How many buttons bar 2 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 2 (страница действий вмещает 12).",
  ["How many buttons bar 3 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 3 (страница действий вмещает 12).",
  ["How many buttons bar 4 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 4 (страница действий вмещает 12).",
  ["How many buttons bar 5 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 5 (страница действий вмещает 12).",
  ["How many buttons bar 6 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 6 (страница действий вмещает 12).",
  ["How many buttons bar 7 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 7 (страница действий вмещает 12).",
  ["How many buttons bar 8 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 8 (страница действий вмещает 12).",
  ["How many buttons bar 9 shows (an action page holds 12)."] = "Сколько кнопок показывает панель 9 (страница действий вмещает 12).",
  ["How many buttons the bin holds."] = "Сколько кнопок вмещает контейнер.",
  ["How many casts each strip shows."] = "Сколько применений показывает каждая полоса.",
  ["How many events the death recap lists before a death."] = "Сколько событий перед смертью перечисляет сводка смерти.",
  ["How many finished fights the Pulse page lists with their times."] = "Сколько завершённых боёв со временем перечисляет страница Pulse.",
  ["How many finished fights to keep across reloads (pinned ones are always kept)."] = "Сколько завершённых боёв хранить между перезагрузками (закреплённые хранятся всегда).",
  ["How many fit in one row before wrapping (overflow goes to the next row)."] = "Сколько помещается в ряд до переноса (излишек — в следующий ряд).",
  ["How many frames before a new column (or row) starts. 5 keeps one group per column."] = "Сколько рамок до начала нового столбца (или ряда). 5 — по одной группе на столбец.",
  ["How many icons fit on one row before a new row starts."] = "Сколько значков помещается в ряд до начала нового.",
  ["How many lines history keeps before the oldest are dropped."] = "Сколько строк хранит история, прежде чем удалять старейшие.",
  ["How many matching groups the panel lists."] = "Сколько подходящих групп перечисляет панель.",
  ["How many meter windows to show (up to 4). Each one has its own meter type and fight; move them in Studio. Different window sets per raid, Mythic+ or arena come from your content profiles."] = "Сколько окон счётчика показывать (до 4). У каждого свой тип счётчика и бой; перемещайте их в Studio. Разные наборы окон для рейда, Эпохального+ или арены задаются профилями контента.",
  ["How many names a chat report lists."] = "Сколько имён перечисляет отчёт в чате.",
  ["How many pulls per boss the history (and the wipe trend) keeps."] = "Сколько пулов на босса хранит история (и тренд вайпов).",
  ["How many rated results are kept (Arena's card reads them too)."] = "Сколько рейтинговых результатов хранится (их читает и карточка арены).",
  ["How many rated results the history window lists (/pui pvphistory)."] = "Сколько рейтинговых результатов перечисляет окно истории (/pui pvphistory).",
  ["How many results the palette lists."] = "Сколько результатов перечисляет палитра.",
  ["How many sample enemies the test mode shows."] = "Сколько пробных противников показывает тестовый режим.",
  ["How many spells the breakdown lists."] = "Сколько заклинаний перечисляет разбивка.",
  ["How many upcoming abilities the list shows."] = "Сколько предстоящих способностей показывает список.",
  ["How much a button darkens while on cooldown."] = "Насколько темнеет кнопка на восстановлении.",
  ["How much bigger critical hits are."] = "Насколько крупнее критические удары.",
  ["How numbered channels are written in front of a line."] = "Как записываются нумерованные каналы перед строкой.",
  ["How often out-of-range units are re-checked (seconds). Lower reacts faster and costs a little more."] = "Как часто перепроверяются юниты вне досягаемости (секунды). Меньше — быстрее реакция, чуть больше затрат.",
  ["How often windows redraw in combat. 0.5 seconds is the fastest; slower saves a little CPU."] = "Как часто окна перерисовываются в бою. 0,5 секунды — быстрее всего; медленнее экономит немного ЦП.",
  ["How quests ready to turn in look."] = "Как выглядят задания, готовые к сдаче.",
  ["How solid the row bars are."] = "Насколько плотны полосы строк.",
  ["How solid the tooltip background is."] = "Насколько плотен фон подсказки.",
  ["How strong the border is (0 hides it, the tab line stays)."] = "Насколько сильна рамка (0 скрывает её, линия вкладок остаётся).",
  ["How strong the hover highlight is."] = "Насколько сильна подсветка наведения.",
  ["How strongly the health bar is tinted."] = "Насколько сильно тонируется полоса здоровья.",
  ["How the bag bar shows. Move it in Studio (Edit Mode owns its position)."] = "Как показывается панель сумок. Перемещайте в Studio (позицией владеет режим редактирования).",
  ["How the fight time is written."] = "Как записывается время боя.",
  ["How the gold block shows money."] = "Как блок золота показывает деньги.",
