  ["If you are fighting when the countdown ends, it waits until you are out of combat."] = "Если вы сражаетесь, когда отсчёт заканчивается, он ждёт выхода из боя.",
  ["If your character shares a name with an addon or a system word, it stays visible inside file paths in reports. Addon folder names and client words are already on this list."] = "Если имя вашего персонажа совпадает с названием аддона или системным словом, оно остаётся видимым в путях файлов в отчётах. Названия папок аддонов и слова клиента уже в этом списке.",
  ["Ignore my own lines"] = "Игнорировать мои строки",
  ["Important aura border colour"] = "Цвет рамки важных эффектов",
  ["Important cast glow colour"] = "Цвет свечения важных применений",
  ["Important or purgeable buffs, right of the plate."] = "Важные или развеиваемые баффы справа от индикатора.",
  ["Imported NPC colour packs"] = "Импортированные наборы цветов NPC",
  ["In Mythic raids only the 20 players in groups 1 to 4 are shown; benched players in groups 5 to 8 are left out."] = "В эпохальных рейдах показываются только 20 игроков групп 1–4; запасные в группах 5–8 не показываются.",
  ["In Mythic+, hide reminders on keys at or above this level (0 never hides)."] = "В Эпохальном+ скрывать напоминания на ключах этого уровня и выше (0 — никогда).",
  ["In Mythic+, how much enemy forces an enemy is worth (data from the M+ tracker)."] = "Сколько сил противника стоит враг в Эпохальном+ (данные из списка M+).",
  ["In Mythic+, shows how much enemy forces each enemy is worth, next to its plate."] = "В Эпохальном+ показывает рядом с индикатором, сколько сил противника стоит каждый враг.",
  ["In arenas and battlegrounds Tab targets the nearest enemy player (an override binding; your own Tab comes back outside)."] = "На аренах и полях боя Tab выбирает ближайшего вражеского игрока (временная привязка; ваш Tab возвращается за их пределами).",
  ["In arenas, a coloured dot for each enemy that is targeting this member (the same colours as your arena frames)."] = "На аренах — цветная точка за каждого противника, выбравшего этого участника целью (те же цвета, что у рамок арены).",
  ["In category and list views, shows one empty slot with the free count instead of every empty slot."] = "В видах категорий и списка показывает одну пустую ячейку с числом свободных вместо всех пустых ячеек.",
  ["In combat, colour enemy plates by your threat. Tanks want aggro; everyone else wants none."] = "В бою окрашивает вражеские индикаторы по вашей угрозе. Танкам нужно агро, остальным — нет.",
