  ["Invite on keyword"] = "Приглашать по ключевому слову",
  ["Invite words"] = "Слова приглашения",
  ["Invites friends, Battle.net friends and guild members who whisper one of your words. Never strangers; never during chat lockdown."] = "Приглашает друзей, друзей Battle.net и членов гильдии, которые шепнули одно из ваших слов. Никогда незнакомцев; никогда во время блокировки чата.",
  ["Item IDs shown in the Pinned category and never sold as junk. Use Pin mode in the bags to add items by clicking."] = "ID предметов, показываемых в категории «Закреплённые» и никогда не продаваемых как хлам. Используйте режим закрепления в сумках, чтобы добавлять щелчком.",
  ["Item IDs shown on the Action Bars item bar and the Cooldown Manager custom bar, in order (for example Healthstone 5512, healing potions, quest items, toys)."] = "ID предметов на панели предметов (Action Bars) и своей панели менеджера восстановления, по порядку (например, камень здоровья 5512, зелья исцеления, предметы заданий, игрушки).",
  ["Item IDs that say when they are ready again (Healthstone is 5512). Potions you add here work the same."] = "ID предметов, сообщающих о готовности (камень здоровья — 5512). Добавленные сюда зелья работают так же.",
  ["Item IDs treated as junk. Use Junk mode in the bags to add items by clicking."] = "ID предметов, считающихся хламом. Используйте режим хлама в сумках, чтобы добавлять щелчком.",
  ["Item IDs whose use is never shown (for example a Healthstone, 5512)."] = "ID предметов, использование которых никогда не показывается (например, камень здоровья, 5512).",
