  ["Junk overlay"] = "Наложение хлама",
  ["Keep Blizzard's buttons, or use Phoenix's matching set (Blizzard's are faded out, never moved)."] = "Оставить кнопки Blizzard или использовать соответствующий набор Phoenix (кнопки Blizzard скрываются, никогда не перемещаются).",
