  ["Keep stats for this character only, or one set for all your characters."] = "Хранить статистику только для этого персонажа или одну для всех ваших персонажей.",
  ["Keeps a list of each character's bag and bank items so you can see them from any character (Bank > Alts)."] = "Хранит список предметов в сумках и банке каждого персонажа, чтобы видеть их с любого персонажа (Банк > Альты).",
  ["Keeps each whisper conversation in its own tab of a small window with a reply box. Never pops up in combat."] = "Держит каждую переписку шёпотом в своей вкладке небольшого окна с полем ответа. Никогда не всплывает в бою.",
  ["Keeps history across reloads and logins. Lines the game kept secret are never stored."] = "Хранит историю между перезагрузками и входами. Строки, скрытые игрой, никогда не сохраняются.",
  ["Keeps recent chat lines so you can search them by text, channel, player and date (/pui chat history)."] = "Хранит недавние строки чата для поиска по тексту, каналу, игроку и дате (/pui chat history).",
  ["Keeps the last 200 Phoenix bus signals (module enabled, profile changes, settings) for /pui trace. Off costs nothing."] = "Хранит последние 200 сигналов шины Phoenix (включение модулей, смены профиля, настройки) для /pui trace. Выключено — ничего не стоит.",
  ["Key countdown (s)"] = "Отсчёт ключа (с)",
