  ["Lists Phoenix fonts, textures and sounds in other addons' pickers (LibSharedMedia), when one of them loads it."] = "Показывает шрифты, текстуры и звуки Phoenix в выборе других аддонов (LibSharedMedia), когда один из них её загружает.",
  ["Lists Rated BG on the rated card."] = "Показывает рейтинговые поля боя в рейтинговой карточке.",
  ["Lists Solo Shuffle on the rated card."] = "Показывает Одиночную потасовку в рейтинговой карточке.",
  ["Lists about 130 Blizzard HUD elements in Studio so you can move, scale, layer, fade or hide them. Edit Mode frames stay with Edit Mode. Off restores every Blizzard element Phoenix changed."] = "Показывает в Studio около 130 элементов HUD Blizzard, чтобы перемещать, масштабировать, наслаивать, приглушать или скрывать их. Рамки режима редактирования остаются в режиме редактирования. Выкл. восстанавливает каждый изменённый Phoenix элемент Blizzard.",
  ["Lists the classes in the group, class-coloured, in the tooltip section."] = "Перечисляет классы группы в цвете классов в разделе подсказки.",
  ["Lists what you picked recently first when the search is empty."] = "Показывает недавно выбранное первым, когда поиск пуст.",
