  ["Map and quest log"] = "Карта и журнал заданий",
  ["Mark Blizzard elements that Edit Mode owns, with a button to open Edit Mode for them."] = "Отмечать элементы Blizzard, которыми владеет режим редактирования, с кнопкой открыть для них режим редактирования.",
  ["Mark casts you cannot interrupt"] = "Отмечать непрерываемые применения",
