  ["Mark rough timings"] = "Отмечать приблизительное время",
  ["Markers, world markers, ready check, pull and break on one small bar. Move it in Studio."] = "Метки, метки на местности, проверка готовности, пул и перерыв на одной маленькой панели. Перемещается в Studio.",
  ["Marks each stage on empowered casts, from the game's own stage timings."] = "Отмечает каждую стадию усиливаемых заклинаний по собственным таймингам стадий игры.",
