  ["Marks upgrades in Phoenix bags (Vault)."] = "Отмечает улучшения в сумках Phoenix (Vault).",
  ["Mask applied to each skinned button's icon."] = "Маска для значка каждой оформленной кнопки.",
  ["Masque skins"] = "Обложки Masque",
  ["Match the player frame width when attached"] = "Ширина как у рамки игрока при прикреплении",
