  ["Material of Phoenix UI windows: Obsidian Glass, Charcoal Solid or Ash Light."] = "Материал окон Phoenix UI: Obsidian Glass, Charcoal Solid или Ash Light.",
  ["Max camera distance"] = "Максимальная дистанция камеры",
