  ["Middle-click on the minimap"] = "Средний щелчок по миникарте",
  ["Minimal: essential cooldowns only. Standard: adds utility cooldowns and buff icons. Everything: adds buff bars. Custom keeps your own choices."] = "Минимальный: только важные восстановления. Стандартный: добавляет вспомогательные восстановления и значки баффов. Всё: добавляет полосы баффов. Свой хранит ваш выбор.",
