  ["Missing flask, food, rune and oil reminders from the season pack (its IDs arrive once checked in game)."] = "Напоминания об отсутствующих настое, еде, руне и масле из сезонного набора (его ID появятся после проверки в игре).",
  ["Missing pet"] = "Нет питомца",
  ["Missing raid buffs, class buffs, pets and your own buff list, checked out of combat, with click to cast."] = "Отсутствующие рейдовые баффы, баффы классов, питомцы и ваш список баффов, проверяемые вне боя, с применением по щелчку.",
