  ["Mouse wheel cycles overlaps"] = "Колесо мыши перебирает наложения",
  ["Move Blizzard windows"] = "Перемещать окна Blizzard",
  ["Moves the DR tray left or right."] = "Сдвигает лоток DR влево или вправо.",
  ["Moves the DR tray up or down."] = "Сдвигает лоток DR вверх или вниз.",
  ["Movie subtitles"] = "Субтитры видео",
  ["Moving strip: new casts push the old ones along. Still and fade: icons stay put and fade out."] = "Движущаяся полоса: новые применения сдвигают старые. Неподвижно и затухание: значки стоят на месте и тускнеют.",
  ["My reminder list"] = "Мой список напоминаний",
  ["My reminders"] = "Мои напоминания",
  ["My roles per spec"] = "Мои роли по специализациям",
  ["Mythic raids: groups 1 to 4 only"] = "Эпохальные рейды: только группы 1–4",
  ["Mythic+ block"] = "Блок Эпохального+",
  ["Mythic+ block on top"] = "Блок Эпохального+ сверху",
  ["Mythic+ block: timer with +2/+3 marks and pace, enemy forces, boss splits, deaths, battle res and Bloodlust, keystones and a run summary."] = "Блок Эпохального+: таймер с отметками +2/+3 и темпом, силы противника, отрезки по боссам, смерти, боевое воскрешение и Жажда крови, ключи и сводка забега.",
  ["Mythic+ enemy forces"] = "Силы противника Эпохального+",
  ["Mythic+ key level, arena, battleground, delve or raid when the game shows it."] = "Уровень ключа Эпохального+, арена, поле боя, вылазка или рейд, когда игра это показывает.",
  ["Mythic+ keystone"] = "Ключ Эпохального+",
  ["Mythic+ run summary"] = "Сводка забега Эпохального+",
  ["Mythic+ score"] = "Рейтинг Эпохального+",
  ["Mythic+ timer: when another addon does this"] = "Таймер Эпохального+: когда это делает другой аддон",
  ["NPC titles"] = "Звания NPC",
  ["Name colour"] = "Цвет имени",
  ["Name position"] = "Положение имени",
  ["Name size"] = "Размер имени",
  ["Name the fight"] = "Название боя",
  ["Nameplates"] = "Индикаторы здоровья",
  ["Names"] = "Имена",
  ["Names longer than the limit become their initials (Shadow Word: Pain -> SWP)."] = "Имена длиннее лимита становятся инициалами (Слово Тьмы: Боль -> СТБ).",
  ["Names of the NPC colour packs to add after your own rules (your own lines always win)."] = "Названия наборов цветов NPC, добавляемых после ваших правил (ваши строки всегда главнее).",
  ["Names your oldest application on the panel and highlights its row."] = "Называет вашу самую старую заявку на панели и подсвечивает её строку.",
  ["Neutral colour"] = "Цвет нейтрального",
  ["Never collect"] = "Никогда не собирать",
  ["Never dim these spells"] = "Никогда не затемнять эти заклинания",
  ["Never leave in combat"] = "Никогда не выходить в бою",
  ["New columns are added to the left instead of the right."] = "Новые столбцы добавляются слева, а не справа.",
  ["New group sound"] = "Звук новой группы",
  ["New item glow"] = "Свечение новых предметов",
  ["New items category"] = "Категория новых предметов",
  ["New members are added above instead of below."] = "Новые участники добавляются сверху, а не снизу.",
  ["New-error popup"] = "Окно новой ошибки",
  ["Newest icon glow"] = "Свечение новейшего значка",
  ["Next abilities list"] = "Список следующих способностей",
  ["Normal colour"] = "Обычный цвет",
  ["Normal text size in this area."] = "Обычный размер текста в этой области.",
  ["Not enough power colour"] = "Цвет нехватки энергии",
  ["Notes"] = "Заметки",
  ["Notes in the panel"] = "Заметки на панели",
  ["Notes scale"] = "Масштаб заметок",
  ["Notes window"] = "Окно заметок",
  ["Notice time"] = "Время уведомления",
  ["Notifications: animation"] = "Уведомления: анимация",
  ["Notifications: direction"] = "Уведомления: направление",
  ["Notifications: most lines per second"] = "Уведомления: максимум строк в секунду",
  ["Notifications: on"] = "Уведомления: вкл.",
  ["Notifications: opacity"] = "Уведомления: прозрачность",
  ["Notifications: scroll height"] = "Уведомления: высота прокрутки",
  ["Notifications: text align"] = "Уведомления: выравнивание текста",
  ["Notifications: text size"] = "Уведомления: размер текста",
  ["Notifications: time on screen (s)"] = "Уведомления: время на экране (с)",
  ["Number font"] = "Шрифт чисел",
  ["Number format"] = "Формат чисел",
  ["Number of icons"] = "Число значков",
  ["Number style"] = "Стиль чисел",
  ["Numbers follow FrameSort"] = "Номера следуют FrameSort",
  ["Objective progress sound"] = "Звук прогресса цели",
  ["Objective tracker"] = "Список целей",
  ["Objectives go from red to green as their count fills."] = "Цели меняют цвет с красного на зелёный по мере заполнения счётчика.",
  ["Off while a boss mod keeps stats"] = "Выкл., пока статистику ведёт модуль боссов",
  ["Off-tank colour"] = "Цвет второго танка",
  ["Off: the All filter lists only Blizzard elements you changed; the Blizzard filter always lists them all."] = "Выкл.: фильтр «Все» показывает только изменённые вами элементы Blizzard; фильтр Blizzard всегда показывает их все.",
  ["On a boss, shows your best saved pull on the same boss and difficulty in the title, and after the pull how you did against it."] = "На боссе показывает в заголовке ваш лучший сохранённый пул на том же боссе и сложности, а после пула — как вы прошли относительно него.",
  ["On: the full log goes to the dashboard, other addons' errors included, so conflicts with Phoenix can be found (same privacy filters: names and paths scrubbed). Off: only Phoenix's own errors leave this PC."] = "Вкл.: полный журнал уходит на панель управления, включая ошибки других аддонов, чтобы находить конфликты с Phoenix (те же фильтры приватности: имена и пути очищаются). Выкл.: этот ПК покидают только ошибки самого Phoenix.",
  ["One NPC per line: its NPC id or exact name, a colour, then optionally a size and 'glow'. Examples: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. The first line for an NPC wins. In some restricted content the game hides NPC ids and names; then a rule waits until they are visible."] = "Один NPC на строку: его ID NPC или точное имя, цвет, затем по желанию размер и 'glow'. Примеры: 185680:B07CFF  -  Void Acolyte:B07CFF:1.1  -  Explosive:FF5468:1.2:glow. Действует первая строка для NPC. В некотором контенте с ограничениями игра скрывает ID и имена NPC; тогда правило ждёт, пока они станут видны.",
  ["One binding per row. Pick a modifier, a mouse button or a key, and what it does: target, menu, focus, assist, cast a spell, run a macro or use an item. Keys work while the mouse is over a frame. Each spec can keep its own list (Editing as). Changes made in combat apply as soon as combat ends."] = "Одна привязка на строку. Выберите модификатор, кнопку мыши или клавишу и действие: цель, меню, фокус, помощь, применить заклинание, выполнить макрос или использовать предмет. Клавиши работают, пока мышь над рамкой. Каждая специализация может хранить свой список («Редактирование для»). Изменения в бою применяются сразу после боя.",
  ["One button per line: bar.button: options. Options: nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash. Example: 1.12:nohotkey,alpha=0.6"] = "Одна кнопка на строку: bar.button: options. Варианты: nohotkey, nomacro, nocount, hide, alpha=0.5, glow=none|pulse|solid|flash. Пример: 1.12:nohotkey,alpha=0.6",
  ["One colour for every glow: the theme's accent. Off keeps each glow's own colour."] = "Один цвет для всех свечений: акцент темы. Выкл. — у каждого свечения свой цвет.",
  ["One font everywhere"] = "Один шрифт везде",
  ["One large icon in the middle for a big personal or external defensive."] = "Один большой значок в центре для крупной личной или внешней защитной способности.",
  ["One line each time your pet becomes unhappy."] = "Одна строка каждый раз, когда питомец становится недовольным.",
  ["One line each: \"Boss name: text\". Lines starting with \"*:\" show for every boss."] = "По строке: \"Имя босса: текст\". Строки, начинающиеся с \"*:\", показываются для всех боссов.",
  ["One line each: \"Original name = New text\". Blank new text hides the name."] = "По строке: \"Исходное имя = Новый текст\". Пустой новый текст скрывает имя.",
  ["One line each: \"spellID: sound\" (a Phoenix or shared sound name), optionally \", removed\" or \", stacks\". The game plays it itself, so it works for private boss debuffs too."] = "По строке: \"spellID: sound\" (название звука Phoenix или общего), по желанию \", removed\" или \", stacks\". Игра проигрывает его сама, поэтому это работает и для скрытых дебаффов боссов.",
  ["One line per boss, by name or encounter ID: \"off\" hides Pulse bars, \"bars=4\" limits bars, \"hud=on\" or \"hud=off\" for the next-abilities list. Example: Dimensius: bars=4 hud=on"] = "По строке на босса, по имени или ID сражения: \"off\" скрывает полосы Pulse, \"bars=4\" ограничивает полосы, \"hud=on\" или \"hud=off\" для списка следующих способностей. Пример: Dimensius: bars=4 hud=on",
  ["One line per click: \"1: target\", \"2: focus\", \"shift-1: spell:Polymorph\", \"ctrl-3: macro:/cast [@arena1] Kick\", \"3: none\". Applied when you leave combat."] = "По строке на щелчок: \"1: target\", \"2: focus\", \"shift-1: spell:Polymorph\", \"ctrl-3: macro:/cast [@arena1] Kick\", \"3: none\". Применяется при выходе из боя.",
  ["One line per reminder: key: sound=SoundName icon=IconID (for example 'oil: sound=Phoenix icon=463543'). Keys: intellect, stamina, lethal, pet, oil, talents, custom12345 ..."] = "По строке на напоминание: key: sound=SoundName icon=IconID (например, 'oil: sound=Phoenix icon=463543'). Ключи: intellect, stamina, lethal, pet, oil, talents, custom12345 ...",
  ["One line per spec: spec ID = roles, e.g. '105 = HEALER, DPS'. Used when Roles per spec is 'My own list'."] = "По строке на специализацию: ID специализации = роли, например '105 = HEALER, DPS'. Используется, когда «Роли по специализациям» — «Мой список».",
  ["One per line as itemID=Category (a built-in id such as consumables, or the name of one of your rules)."] = "По одному на строку: itemID=Категория (встроенный id, например consumables, или название одного из ваших правил).",
  ["One per line: a spell ID, optionally followed by :name (for example 1234:Flask). Shows when you lack that buff."] = "По одному на строку: ID заклинания, по желанию :название (например, 1234:Flask). Показывается, когда у вас нет этого баффа.",
  ["One search across friends, guild and recent players, with sort and actions, beside the friends list."] = "Единый поиск по друзьям, гильдии и недавним игрокам, с сортировкой и действиями, рядом со списком друзей.",
  ["One section per addon (collapsible, with counts, first and last seen and the session), or a single newest-first list."] = "По разделу на аддон (сворачиваемый, со счётчиками, первым и последним появлением и сеансом) или единый список, новые сверху.",
  ["One setting for every place roles are set: manual, the role your spec plays, or your own list below. Auto stands down while BigWigs sets roles."] = "Одна настройка для всех мест, где задаются роли: вручную, роль вашей специализации или ваш список ниже. «Авто» отключается, пока роли задаёт BigWigs.",
  ["One switch for every chat announcement Phoenix modules can make. Modules only pick what to say; where it goes is set here."] = "Один переключатель для всех объявлений в чат, которые могут делать модули Phoenix. Модули выбирают только что сказать; куда — задаётся здесь.",
  ["Online friends count on the minimap; hover it for the list."] = "Число друзей в сети на миникарте; наведите для списка.",
  ["Online friends' names in their class colour."] = "Имена друзей в сети в цвете класса.",
  ["Only DR I can trigger"] = "Только DR, который я могу вызвать",
  ["Only cooldowns longer than (s)"] = "Только восстановления дольше (с)",
  ["Only debuffs your class and spec can remove, or any dispellable debuff (useful to call for help)."] = "Только дебаффы, которые может снять ваш класс и специализация, или любой рассеиваемый дебафф (полезно, чтобы звать на помощь).",
  ["Only in combat"] = "Только в бою",
  ["Only online players in the search panel."] = "Только игроки в сети в панели поиска.",
  ["Only tanks and healers get a role marker."] = "Отметку роли получают только танки и лекари.",
  ["Opacity"] = "Прозрачность",
  ["Opacity of a frame whose unit is out of range."] = "Прозрачность рамки, чей юнит вне досягаемости.",
  ["Opacity of bar 1 while faded."] = "Прозрачность панели 1 при затухании.",
