  ["Opacity of out-of-range frames."] = "Прозрачность рамок вне досягаемости.",
  ["Opacity of plates that are not your target while you have one; 1 keeps them fully visible."] = "Прозрачность индикаторов, не являющихся вашей целью, когда она есть; 1 — полностью видимы.",
  ["Opacity of the bars."] = "Прозрачность полос.",
  ["Opacity of the chat panel."] = "Прозрачность панели чата.",
  ["Opacity of the dark background behind Phoenix bars."] = "Прозрачность тёмного фона за полосами Phoenix.",
  ["Opacity of the empty part of each bar."] = "Прозрачность пустой части каждой полосы.",
  ["Opacity of the health fill."] = "Прозрачность заливки здоровья.",
  ["Opacity of the item bar while faded."] = "Прозрачность панели предметов при затухании.",
  ["Opacity of the pet bar while faded."] = "Прозрачность панели питомца при затухании.",
  ["Opacity of the stance bar while faded."] = "Прозрачность панели стоек при затухании.",
  ["Opacity of the text."] = "Прозрачность текста.",
  ["Opacity of the vehicle exit button while faded."] = "Прозрачность кнопки выхода из транспорта при затухании.",
  ["Opacity of the whole tracker."] = "Прозрачность всего списка.",
  ["Opacity out of combat"] = "Прозрачность вне боя",
  ["Opacity used when the where-to-show rule hides the frame (0 = invisible, higher = faded)."] = "Прозрачность, когда правило «где показывать» скрывает рамку (0 = невидима, больше = приглушена).",
  ["Opacity used when the where-to-show rule hides the frames (0 = invisible). They stay clickable in combat because the game locks that."] = "Прозрачность, когда правило «где показывать» скрывает рамки (0 = невидимы). В бою они остаются кликабельными, потому что игра это блокирует.",
  ["Open Phoenix Studio button"] = "Кнопка открытия Phoenix Studio",
  ["Open a blocked report in the copy box"] = "Открывать заблокированный отчёт в поле копирования",
  ["Open containers"] = "Открывать контейнеры",
  ["Open key"] = "Клавиша открытия",
  ["Open recap when I die"] = "Открывать сводку, когда я умираю",
  ["Open the bin by"] = "Открывать контейнер",
  ["Open the scoreboard after a battleground"] = "Открывать таблицу результатов после поля боя",
  ["Open the viewer on a new error"] = "Открывать окно просмотра при новой ошибке",
  ["Opens Phoenix's scoreboard when a battleground ends."] = "Открывает таблицу результатов Phoenix по окончании поля боя.",
  ["Opens at"] = "Открывается на",
  ["Opens beside Blizzard's PvP window, or only with /pui pvp card."] = "Открывается рядом с окном PvP Blizzard или только через /pui pvp card.",
  ["Opens lootable bag items (caches, satchels) one at a time out of combat. Hold Shift to keep them closed."] = "Открывает предметы с добычей в сумках (тайники, сумки) по одному вне боя. Удерживайте Shift, чтобы не открывать.",
  ["Opens the error viewer by itself. Never during combat: it waits until the fight ends."] = "Сам открывает окно ошибок. Никогда в бою: ждёт окончания боя.",
  ["Opens your death recap automatically when you die."] = "Автоматически открывает сводку смерти, когда вы умираете.",
  ["Optional: the season's achievement ID, so the count comes from the game. 0 = automatic (Gladiator) or Phoenix's count."] = "Необязательно: ID достижения сезона, чтобы счёт брался из игры. 0 = автоматически («Гладиатор») или счёт Phoenix.",
  ["Options mode"] = "Режим настроек",
  ["Oracle"] = "Oracle",
  ["Oracle search"] = "Поиск Oracle",
  ["Order of Phoenix's list, e.g. 'mprating desc, age asc'. Empty keeps Blizzard's order."] = "Порядок списка Phoenix, например 'mprating desc, age asc'. Пусто — порядок Blizzard.",
  ["Order of categories, highest first. Words: cc, defensive, important. Leave one out to never show it (\"cc\" alone shows only crowd control)."] = "Порядок категорий, сначала высшие. Слова: cc, defensive, important. Пропустите одно, чтобы никогда его не показывать (\"cc\" отдельно показывает только контроль).",
  ["Order of the party frames."] = "Порядок рамок группы.",
  ["Order of the search panel."] = "Порядок панели поиска.",
  ["Order raid frames by group, by role (in the role order below), by class or by name."] = "Упорядочивать рамки рейда по группе, по роли (в порядке ролей ниже), по классу или по имени.",
  ["Order used when sorting by role (raid and party)."] = "Порядок при сортировке по роли (рейд и группа).",
  ["Other plates' opacity"] = "Прозрачность остальных индикаторов",
  ["Other players' item level and specialization (asked from the server once, then remembered for 5 minutes; never in combat)."] = "Уровень предметов и специализация других игроков (запрашивается у сервера один раз, затем запоминается на 5 минут; никогда в бою).",
