  ["Overrides for single instances: 'instance ID:option=on' or '=off'. An instance without a line follows its content type. Inside an instance, /pui quiet here <option> on|off|inherit adds or removes a line."] = "Переопределения для отдельных подземелий: 'instance ID:option=on' или '=off'. Подземелье без строки следует своему типу контента. Внутри подземелья /pui quiet here <option> on|off|inherit добавляет или удаляет строку.",
