  ["Pets, guardians and other summons controlled by players get a smaller plate."] = "Питомцы, стражи и прочие призванные игроками существа получают меньший индикатор.",
  ["Phoenix action bars hide while a controller is active, for controller addons that bring their own bars."] = "Панели команд Phoenix скрываются, пока активен контроллер, для аддонов контроллера со своими панелями.",
  ["Phoenix action bars hide while you are inside a player house and come back when you leave."] = "Панели команд Phoenix скрываются, пока вы в доме игрока, и возвращаются, когда вы уходите.",
  ["Phoenix action bars with paging, where-to-show rules, mouse-over fade, keybind mode, cooldowns, range colouring and proc glow, plus stance, pet, vehicle exit and item bars."] = "Панели команд Phoenix со сменой страниц, правилами «где показывать», затуханием до наведения, режимом привязок, восстановлениями, окраской по дальности и свечением срабатываний, а также панели стоек, питомца, выхода из транспорта и предметов.",
  ["Phoenix background and border on tooltips; off keeps Blizzard's look."] = "Фон и рамка Phoenix у подсказок; выкл. — вид Blizzard.",
  ["Phoenix bank window"] = "Окно банка Phoenix",
  ["Phoenix bars and names use the class colours below instead of the game's."] = "Полосы и имена Phoenix используют цвета классов ниже вместо игровых.",
  ["Phoenix bars for breath, fatigue and feign death timers."] = "Полосы Phoenix для таймеров дыхания, усталости и притворной смерти.",
  ["Phoenix border and tabs"] = "Рамка и вкладки Phoenix",
  ["Phoenix boxes; the check mark takes the accent colour."] = "Флажки Phoenix; галочка получает цвет акцента.",
  ["Phoenix builds this many plates out of combat so big pulls never build frames mid-fight."] = "Phoenix создаёт столько индикаторов вне боя, чтобы большие пулы никогда не создавали рамки посреди боя.",
  ["Phoenix button face on Blizzard panel buttons."] = "Лицевая сторона кнопок Phoenix на кнопках панелей Blizzard.",
  ["Phoenix chat bubbles in the open world (Blizzard locks them inside instances)."] = "Облачка чата Phoenix в открытом мире (Blizzard блокирует их в подземельях).",
  ["Phoenix draws this frame, Blizzard shows the default frame, or hidden shows neither."] = "Phoenix рисует эту рамку, Blizzard показывает стандартную, или «скрыто» — ни одну.",
  ["Phoenix draws your buffs and debuffs in two movable rows, or Blizzard's default buff frame stays."] = "Phoenix рисует ваши баффы и дебаффы в двух перемещаемых рядах, или остаётся стандартная рамка баффов Blizzard.",
  ["Phoenix dropdown boxes with an accent arrow."] = "Выпадающие списки Phoenix со стрелкой цвета акцента.",
  ["Phoenix ember backdrop behind mount and pet models."] = "Фон с искрами Phoenix за моделями транспорта и питомцев.",
  ["Phoenix ember backdrop behind the character model."] = "Фон с искрами Phoenix за моделью персонажа.",
  ["Phoenix emoji art"] = "Изображения смайлов Phoenix",
  ["Phoenix error reports go to the vq8s.com dashboard through the Companion app (and the export string works). See exactly what leaves this PC with Preview on the error reporter. Nothing is shared while off."] = "Отчёты об ошибках Phoenix уходят на панель vq8s.com через приложение Companion (и строка экспорта работает). Посмотреть, что именно покидает этот ПК, можно через «Предпросмотр» в окне отчёта об ошибке. При выключении ничего не передаётся.",
  ["Phoenix font on cinematic subtitles."] = "Шрифт Phoenix в субтитрах роликов.",
  ["Phoenix fonts and bars on top-centre and minimap widgets and the encounter power bar."] = "Шрифты и полосы Phoenix на виджетах вверху по центру и у миникарты и на полосе энергии сражения.",
  ["Phoenix fonts on raid warnings, boss emotes and the red error text."] = "Шрифты Phoenix для объявлений рейду, эмоций боссов и красного текста ошибок.",
  ["Phoenix frame skin for Details! windows when that addon is installed."] = "Оформление рамок Phoenix для окон Details!, если этот аддон установлен.",
  ["Phoenix frame skin for Pawn when that addon is installed."] = "Оформление рамок Phoenix для Pawn, если этот аддон установлен.",
  ["Phoenix frame skin for Plater options when that addon is installed."] = "Оформление рамок Phoenix для настроек Plater, если этот аддон установлен.",
  ["Phoenix frame skin for WeakAuras options when that addon is installed."] = "Оформление рамок Phoenix для настроек WeakAuras, если этот аддон установлен.",
  ["Phoenix input boxes with a hairline border."] = "Поля ввода Phoenix с тонкой рамкой.",
  ["Phoenix keybinds"] = "Привязки клавиш Phoenix",
  ["Phoenix look for Blizzard's windows, menus, tooltips and popups (their own layout and features, your theme), and Details!, Pawn, WeakAuras and Plater; each has its own switch."] = "Вид Phoenix для окон, меню, подсказок и всплывающих окон Blizzard (их собственная раскладка и функции, ваша тема), а также Details!, Pawn, WeakAuras и Plater; у каждого свой переключатель.",
  ["Phoenix look for every context menu and dropdown list, including the damage meter's."] = "Вид Phoenix для всех контекстных меню и выпадающих списков, включая счётчик урона.",
  ["Phoenix look on Blizzard's meter"] = "Вид Phoenix на счётчике Blizzard",
  ["Phoenix look on flyouts"] = "Вид Phoenix на выпадающих панелях",
  ["Phoenix minimap: shape, border, texts, coordinates, queue countdown, addon button bin and more."] = "Миникарта Phoenix: форма, рамка, тексты, координаты, отсчёт очереди, контейнер кнопок аддонов и многое другое.",
  ["Phoenix nameplates: enemy and friendly styles, threat and NPC colours, cast bars with your interrupt, aura lanes, target and focus highlights, quest, execute and Mythic+ forces indicators."] = "Индикаторы здоровья Phoenix: стили для врагов и союзников, цвета угрозы и NPC, полосы заклинаний с вашим прерыванием, дорожки эффектов, подсветка цели и фокуса, индикаторы заданий, добивания и сил Эпохального+.",
  ["Phoenix only restyles the cooldown icons and bars; their places, sizes and which ones show stay as Blizzard's Cooldown Manager sets them (from the game's next layout pass). The safest mode for testing."] = "Phoenix только меняет вид значков и полос восстановления; их места, размеры и состав остаются такими, как их задаёт менеджер восстановления Blizzard (со следующего прохода раскладки игры). Самый безопасный режим для тестирования.",
  ["Phoenix panel"] = "Панель Phoenix",
  ["Phoenix panel on Blizzard's tutorial help tips."] = "Панель Phoenix на обучающих подсказках Blizzard.",
  ["Phoenix party and raid frames: layouts by group size, sorting, role icons, dispel highlight, aura icons, corner indicators, private auras, heal prediction, range fade and a test mode."] = "Рамки группы и рейда Phoenix: раскладки по размеру группы, сортировка, значки ролей, подсветка рассеивания, значки эффектов, угловые индикаторы, скрытые эффекты, прогноз исцеления, затухание по дальности и тестовый режим.",
  ["Phoenix pet bar (hides the Blizzard one)."] = "Панель питомца Phoenix (скрывает панель Blizzard).",
  ["Phoenix player, target, focus, pet, target-of-target, focus-target and boss frames, and your buff and debuff rows."] = "Рамки Phoenix для игрока, цели, фокуса, питомца, цели цели, цели фокуса и боссов, а также ряды ваших баффов и дебаффов.",
  ["Phoenix positions the game's buff bars in its own rows; off leaves them to the game."] = "Phoenix размещает полосы баффов игры в своих рядах; выкл. оставляет их игре.",
  ["Phoenix positions the game's buff icons in its own rows; off leaves them to the game."] = "Phoenix размещает значки баффов игры в своих рядах; выкл. оставляет их игре.",
  ["Phoenix positions the game's essential cooldowns in its own rows; off leaves them to the game."] = "Phoenix размещает важные восстановления игры в своих рядах; выкл. оставляет их игре.",
  ["Phoenix positions the game's utility cooldowns in its own rows; off leaves them to the game."] = "Phoenix размещает вспомогательные восстановления игры в своих рядах; выкл. оставляет их игре.",
