  ["Phoenix's look on the friends list, zone and activity per friend, one search across friends, guild and recent players, and invite accept per source (off)."] = "Вид Phoenix в списке друзей, зона и занятие каждого друга, единый поиск по друзьям, гильдии и недавним игрокам и принятие приглашений по источникам (выкл.).",
  ["Phoenix, Glass, Blizzard-like, compact or text-only rows. Every part of a look can also be changed below."] = "Строки Phoenix, Glass, как у Blizzard, компактные или только текст. Каждую часть вида можно изменить ниже.",
  ["Pick the fight from a list"] = "Выбирать бой из списка",
