  ["Pick the meter from a list"] = "Выбирать счётчик из списка",
  ["Pick, per content type, whether the profile switches and whether a chat line tells you."] = "Выберите для каждого типа контента, переключается ли профиль и сообщает ли об этом строка в чате.",
  ["Pick, per reminder group, the content types where it shows."] = "Выберите для каждой группы напоминаний типы контента, где она показывается.",
  ["Picks the only dialogue option when there is no quest. Hold Shift to read."] = "Выбирает единственный вариант диалога, когда нет задания. Удерживайте Shift, чтобы прочитать.",
