  ["Presses Sign Up on Blizzard's sign-up window with your roles. Hold Shift while signing up to choose yourself. Blizzard runs this window with protected code; an addon helping here can, rarely, cause an 'interface action blocked' message. It is on by default because you chose so; turn it off if you ever see that."] = "Нажимает «Записаться» в окне записи Blizzard с вашими ролями. Удерживайте Shift при записи, чтобы выбрать самому. Blizzard запускает это окно защищённым кодом; помощь аддона здесь изредка может вызвать сообщение «действие интерфейса заблокировано». Включено по умолчанию, потому что вы так выбрали; выключите, если когда-нибудь увидите его.",
