  ["Realm language badge"] = "Значок языка сервера",
  ["Recent casts for you, your target, focus, party and arena enemies. The one owner of spell history; the damage meter links here."] = "Недавние заклинания ваши, вашей цели, фокуса, группы и врагов на арене. Единый владелец истории заклинаний; счётчик урона ссылается сюда.",
  ["Recent deaths listed under the timer; click one to open its Embers recap."] = "Недавние смерти под таймером; щёлкните, чтобы открыть их разбор в Embers.",
  ["Recolour in execute range"] = "Перекрашивать в зоне добивания",
  ["Records each character's gold once a day; hover the gold line to see every character and the last week."] = "Записывает золото каждого персонажа раз в день; наведите на строку золота, чтобы увидеть всех персонажей и последнюю неделю.",
  ["Records zone, combat, group size, frame-rate band and Phoenix errors, one row per change, into your saved data (/pui record). Off records nothing."] = "Записывает зону, бой, размер группы, диапазон частоты кадров и ошибки Phoenix, по строке на изменение, в ваши сохранённые данные (/pui record). Выкл. ничего не записывает.",
  ["Red below (seconds)"] = "Красный ниже (секунды)",
