  ["Reduced motion"] = "Меньше анимации",
  ["Refresh every (seconds)"] = "Обновлять каждые (секунды)",
  ["Region tags"] = "Метки регионов",
  ["Releases your spirit on death. World only, or also in dungeons and raids; never in battlegrounds or arenas, and never when you can self-resurrect."] = "Освобождает дух при смерти. Только в мире или также в подземельях и рейдах; никогда на полях боя и аренах и никогда, если вы можете воскреснуть сами.",
  ["Remember items for alts"] = "Запоминать предметы для альтов",
