  ["Reminds warlocks and hunters (not Marksmanship) to summon their pet."] = "Напоминает чернокнижникам и охотникам (кроме стрельбы) призвать питомца.",
  ["Reminds you to switch to the talent loadout you saved for this instance (/pui rmtalents save)."] = "Напоминает переключиться на набор талантов, сохранённый для этого подземелья (/pui rmtalents save).",
  ["Reminds you when your main-hand weapon has no oil or other temporary enchant inside an instance."] = "Напоминает, если на оружии в правой руке нет масла или другого временного улучшения в подземелье.",
